SELECT SUM(100) OVER (PARTITION BY "deptno", "sal" ORDER BY "sal" RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col1", SUM(100) OVER (PARTITION BY "sal" ORDER BY "deptno" RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col2", SUM("sal") OVER (PARTITION BY "deptno" ORDER BY "sal" RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS "col3"
FROM "emp"
WHERE "sal" = 5000;
